import streamlit as st
from src.translations import t
from src.ui import heading


def render(db):
    heading(t('AI University Complaint Management System','AI университет шағымдарын басқару жүйесі'),t('Master’s final project · AI Essentials · Astana IT University','Магистрлік қорытынды жоба · AI Essentials · Astana IT University'))
    st.markdown('<div class="hero"><h3>'+t('Kazakh NLP, with human responsibility.','Қазақ тілін өңдеу және адам жауапкершілігі.')+'</h3><p>'+t('A research demonstration of intelligent complaint analysis and confidence-aware routing.','Шағымдарды зияткерлік талдау және сенімділікке негізделген бағыттаудың зерттеу демонстрациясы.')+'</p></div>',unsafe_allow_html=True)
    st.warning(t('This is an academic prototype, not an official Astana IT University complaint-processing system. There is no authentication or role-based authorization.','Бұл — академиялық прототип, Astana IT University ресми шағым өңдеу жүйесі емес. Аутентификация және рөлдік рұқсаттар жоқ.'))
    sections=[
      (('Background & research problem','Алғышарт және зерттеу мәселесі'),('University complaints arrive as unstructured text. Identifying the topic, urgency, emotional tone, and responsible department can help administrators respond consistently. This project investigates these tasks for Kazakh, a language with comparatively limited NLP resources.','Университет шағымдары құрылымсыз мәтін түрінде түседі. Тақырыпты, шұғылдықты, эмоциялық реңкті және жауапты бөлімді анықтау әкімшіліктің жүйелі жауап беруіне көмектеседі. Жоба бұл міндеттерді NLP ресурстары салыстырмалы түрде аз қазақ тілі үшін зерттейді.')),
      (('Research objectives','Зерттеу мақсаттары'),('Compare classical, recurrent, multilingual Transformer, and Kazakh Transformer approaches on the same split; jointly predict four labels; evaluate held-out Macro-F1 and urgency errors; investigate confidence-aware routing with human review.','Бірдей бөлінген деректерде классикалық, рекуррентті, көптілді Transformer және қазақша Transformer тәсілдерін салыстыру; төрт белгіні бірге болжау; тест Macro-F1 мен шұғылдық қателерін бағалау; адам тексеруі бар сенімділікке негізделген бағыттауды зерттеу.')),
      (('Dataset & methodology','Деректер жиыны және әдістеме'),('The supplied dataset contains 1,000 Kazakh university complaints: 700 training, 150 validation, and 150 testing examples. Seed 42, stratified by category × urgency. Text is normalized with Unicode NFC, selected invisible characters are removed, and whitespace is collapsed. Four targets have 3, 3, 3, and 6 classes. Neural models use the sum of four classification losses. Model selection and routing experiments use validation; final metrics use the held-out test set.','Берілген деректер жиынында қазақша 1 000 университет шағымы бар: 700 үйрету, 150 валидация және 150 тест мысалы. Seed 42, санат × шұғылдық бойынша стратификацияланған. Мәтін Unicode NFC арқылы қалыпқа келтіріледі, кейбір көрінбейтін таңбалар жойылып, бос орындар ықшамдалады. Төрт міндетте 3, 3, 3 және 6 класс бар. Нейрондық модельдер төрт жіктеу шығынының қосындысын пайдаланады. Модель таңдау мен бағыттау тәжірибелері валидацияда, қорытынды көрсеткіштер бөлек тест жиынында есептеледі.')),
      (('Architectures & main results','Архитектуралар және негізгі нәтижелер'),('Linear SVM with character TF-IDF achieved the best mean Macro-F1 (0.9731). BiLSTM with attention achieved the best urgency F1 (0.9790). XLM-RoBERTa provides a multilingual comparison. KazRoBERTa achieved the best category F1 (0.9933) and is deployed here to demonstrate a shared-encoder, four-head Transformer. The application uses existing weights; it does not retrain models.','Таңбалық TF-IDF бар Linear SVM ең жоғары орташа Macro-F1 (0.9731) көрсетті. Attention бар BiLSTM шұғылдық бойынша ең жоғары F1 (0.9790) көрсетті. XLM-RoBERTa көптілді салыстыруды қамтамасыз етеді. KazRoBERTa санат бойынша ең жоғары F1 (0.9933) көрсетті және мұнда ортақ кодтағышы, төрт басы бар Transformer демонстрациясы үшін қолданылады. Қолданба дайын салмақтарды қолданады; модельдерді қайта үйретпейді.')),
      (('Confidence-aware routing','Сенімділікке негізделген бағыттау'),('Routing confidence is the minimum of the maximum category, urgency, and department probabilities; tone is excluded. Manual review is required when confidence < 0.75 OR P(high urgency) ≥ 0.30. Potential urgency sets a high operational review priority independently of the model’s predicted urgency. The 4 / 24 / 72-hour SLA suggestions are research examples, not official policy. Human edits and original predictions are stored separately with change history.','Бағыттау сенімділігі — санат, шұғылдық және бөлімнің ең жоғары ықтималдықтарының минимумы; реңк есепке алынбайды. Сенімділік < 0.75 НЕМЕСЕ P(жоғары шұғылдық) ≥ 0.30 болса, қолмен тексеру қажет. Ықтимал шұғылдық модель болжаған шұғылдықтан тәуелсіз жоғары тексеру басымдығын береді. 4 / 24 / 72 сағаттық SLA ұсыныстары — ресми саясат емес, зерттеу мысалдары. Адам түзетулері мен бастапқы болжамдар өзгерістер тарихымен бірге бөлек сақталады.')),
      (('Limitations & responsible AI','Шектеулер және жауапты AI'),('The dataset is small and has similar textual patterns across splits. Its non-group-aware split may overestimate real-world performance. Softmax scores are uncalibrated. Critical urgency can be missed even with high confidence. Local storage is not encrypted by this app, and there is no access-control layer. Use anonymized demonstration text, protect the device, and avoid sharing exported sensitive records. This tool supports human judgment and cannot autonomously resolve critical safety incidents.','Деректер жиыны шағын және оның бөліктерінде ұқсас мәтіндік құрылымдар бар. Топтарды ескермеген бөлу нақты әлемдегі нәтижені асыра бағалауы мүмкін. Softmax бағалары калибрленбеген. Жоғары сенімділік кезінде де аса шұғыл жағдай анықталмауы мүмкін. Қолданба жергілікті сақтауды шифрламайды және қолжетімділікті басқармайды. Иесіздендірілген демонстрациялық мәтінді қолданыңыз, құрылғыны қорғаңыз және құпия экспорттарды таратпаңыз. Құрал адам пайымын қолдайды, аса қауіпті оқиғаларды дербес шеше алмайды.')),
      (('Future improvements','Болашақ жетілдірулер'),('Larger consented datasets, group-aware and multi-university evaluation, multiple training seeds, probability calibration, urgency-sensitive objectives, robustness to code-switching and spelling variation, proper authentication, encryption and retention controls, and institution-approved routing policies.','Келісіммен жиналған үлкен деректер жиындары, топтарды ескеретін және бірнеше университеттегі бағалау, бірнеше үйрету seed-і, ықтималдықтарды калибрлеу, шұғылдыққа сезімтал мақсаттар, тіл араластыру мен емле өзгерістеріне төзімділік, толық аутентификация, шифрлау мен сақтау мерзімін бақылау және мекеме мақұлдаған бағыттау саясаты.')),
    ]
    for title,body in sections:
        with st.container(border=True):
            st.subheader(t(*title));st.write(t(*body))
